function removeNthFromEnd(head, n) {
  const dummy = new ListNode(0, head); // lets us remove the head too
  let fast = dummy;
  let slow = dummy;
  for (let i = 0; i < n; i++) fast = fast.next; // open a gap of n nodes
  while (fast.next !== null) { // until fast sits on the last node
    fast = fast.next;
    slow = slow.next;
  }
  slow.next = slow.next.next; // slow is right before the target
  return dummy.next;
}

public ListNode removeNthFromEnd(ListNode head, int n) {
