    for (int i = 0; i < n; i++) fast = fast.next; // open a gap of n nodes
    while (fast.next != null) { // until fast sits on the last node
        fast = fast.next;
        slow = slow.next;
    }
    slow.next = slow.next.next; // slow is right before the target
    return dummy.next;
}

function reorderList(head) {
  if (head === null || head.next === null) return;
  // 1) find the end of the first half
  let slow = head, fast = head;
  while (fast.next !== null && fast.next.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
  }
  // 2) cut after slow and reverse the second half
  let prev = null, curr = slow.next;
  slow.next = null;
  while (curr !== null) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  // 3) weave: first, last, second, second-last, ...
  let first = head, second = prev;
  while (second !== null) {
    const n1 = first.next, n2 = second.next;
    first.next = second;
    second.next = n1;
    first = n1;
    second = n2;
  }
}

