class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map(); // key -> node
    this.head = { prev: null, next: null }; // sentinel, most-recent side
    this.tail = { prev: null, next: null }; // sentinel, least-recent side
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  #remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  #addFront(node) {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next.prev = node;
    this.head.next = node;
  }
  get(key) {
    const node = this.map.get(key);
    if (!node) return -1;
    this.#remove(node);
    this.#addFront(node); // now the most recently used
    return node.val;
  }
  put(key, value) {
    if (this.map.has(key)) {
      this.#remove(this.map.get(key)); // replaced by a fresh node below
    } else if (this.map.size === this.capacity) {
      const lru = this.tail.prev; // least recently used entry
      this.#remove(lru);
      this.map.delete(lru.key);
    }
    const node = { key, val: value, prev: null, next: null };
    this.map.set(key, node);
    this.#addFront(node); // newest entry goes to the front
  }
}

