class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.map = {}  # key -> Node
        self.head, self.tail = Node(), Node()  # sentinels
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _add_front(self, node):
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key: int) -> int:
        node = self.map.get(key)
        if node is None:
            return -1
        self._remove(node)
        self._add_front(node)  # now the most recently used
        return node.val

    def put(self, key: int, value: int) -> None:
        if key in self.map:
            self._remove(self.map[key])
        elif len(self.map) == self.capacity:
            lru = self.tail.prev  # least recently used entry
            self._remove(lru)
            del self.map[lru.key]
        node = Node(key, value)
        self.map[key] = node
        self._add_front(node)

class LRUCache {
    private static class Node {
        int key, val; Node prev, next;
        Node(int key, int val) { this.key = key; this.val = val; }
    }
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>(); // key -> node (O(1) lookup)
    private final Node head = new Node(0, 0), tail = new Node(0, 0); // sentinels
    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail; tail.prev = head; // empty list: head <-> tail
    }
    private void remove(Node node) { // O(1): the node knows both neighbours
        node.prev.next = node.next; node.next.prev = node.prev;
    }
    private void addFront(Node node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }
    public int get(int key) {
        Node node = map.get(key);
        if (node == null) return -1;
        remove(node);
        addFront(node); // now the most recently used
        return node.val;
    }
    public void put(int key, int value) {
        if (map.containsKey(key)) remove(map.get(key)); // replaced below
        else if (map.size() == capacity) {
            Node lru = tail.prev; // least recently used entry
            remove(lru);
            map.remove(lru.key);
        }
        Node node = new Node(key, value);
        map.put(key, node);
        addFront(node); // newest entry goes to the front
    }
}

